import json, pathlib
p=pathlib.Path('output/build-ideas')
c=json.load(open('public/data/catalog.json'))
ids=['wildflowers','plainstool','campfire']
items=[i for i in c['items'] if i['id'] in ids]
placements=[{'id':f'flower-{n+1}','itemId':'wildflowers','x':x,'y':y,'z':0,'rotation':0,'footprint':{'width':1,'depth':1,'status':'illustrative'}} for n,(x,y) in enumerate([(0,0),(1,0),(0,1),(1,1)])]
placements += [{'id':a,'itemId':b,'x':x,'y':y,'z':0,'rotation':0,'footprint':{'width':1,'depth':1,'status':'illustrative'}} for a,b,x,y in [('seat-1','plainstool',1,3),('seat-2','plainstool',3,3),('fire-1','campfire',2,2)]]
r={'schemaVersion':1,'id':'demo-flower-camp','version':1,'title':'Flower camp','kind':'outdoor-decoration-concept','publicationStatus':'prototype-only','catalogVersion':c['version'],'authorship':{'name':'Companion concept','kind':'original-prototype','note':'Not a reconstruction of a player build.'},'plot':{'width':5,'depth':5,'height':1,'status':'illustrative','baseTerrain':'Existing level ground; terrain quantity not included.'},'pokemonIds':['eevee','combee'],'items':items,'placements':placements,'billOfItems':[{'itemId':i,'quantity':sum(x['itemId']==i for x in placements),'basis':'counted from prototype placements','role':'required-to-recreate-this-concept'} for i in ids],'rawMaterials':None,'sources':[{'id':'habitat-requirement','url':'https://www.serebii.net/pokemonpokopia/habitatdex/prettyflowerbed.shtml','checkedAt':'2026-09-12','supports':['Pretty flower bed requires four Wildflowers'],'doesNotSupport':['this 5x5 layout','furniture footprints','group housing','comfort result']},{'id':'catalog','path':'public/data/catalog.json','supports':['item IDs','item preference categories','Pokemon preferences']}],'candidateSource':{'url':'https://www.reddit.com/r/Pokemon_Pokopia/comments/1t583yp/welcome_to_the_5x5_habitat_gallery/','creator':'CanStriking2668','playlistUrl':'https://youtube.com/playlist?list=PL4lweZ0eQ3QR1Gq25o6CuYAqcIi_YUQkc','status':'discovery-only','selectedVideo':None,'timestamps':[],'reuseStatus':'not-established','note':'No layout or media from this creator is copied into this concept.'},'review':{'catalogIds':'checked','quantityArithmetic':'checked','footprints':'not-verified','placementRules':'not-verified','inGameRecreation':'not-tested','sourceReconstruction':'not-applicable-original-concept','publishable':False,'blockers':['Verify footprints and placement rules','Recreate in game and record evidence','For a community template: select exact tutorial, establish reuse, map every object and layer']},'matching':{'basis':'exact overlap of Pokemon favorites and catalog item categories','claimsExcluded':['confirmed comfort','resident capacity','simultaneous attraction','type-based compatibility']},'persistencePolicy':{'namespace':'build-ideas-prototype-v1','templateVersionPinned':True,'inventoryConsumption':False}}
(p/'sample-build.json').write_text(json.dumps(r,indent=2)+'\n')
(p/'sample-data.js').write_text('window.BUILD_SAMPLE='+json.dumps(r)+';\nwindow.POKEMON_SAMPLE='+json.dumps([{'id':i['id'],'name':i['name'],'favorites':i['favorites']} for i in c['pokemon'] if i['id'] in ['eevee','combee','magby']])+';\n')
